public class ImportStatementOrganizerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void finish() {
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }

    static java.util.List<String> list(String... values) {
        return new java.util.ArrayList<>(java.util.Arrays.asList(values));
    }

    public static void main(String[] args) {
        check("importedName of a plain import", "java.util.Map",
                ImportStatementOrganizer.importedName("import java.util.Map;"));
        check("importedName of an indented static import", "java.lang.Math.max",
                ImportStatementOrganizer.importedName("  import static java.lang.Math.max;"));
        check("isStatic true", true, ImportStatementOrganizer.isStatic("import static java.lang.Math.max;"));
        check("isStatic false", false, ImportStatementOrganizer.isStatic("import java.util.Map;"));
        check("sorted with statics last",
                "[import java.util.ArrayList;, import java.util.Map;, import static java.lang.Math.max;]",
                String.valueOf(ImportStatementOrganizer.organize(list(
                        "import java.util.Map;",
                        "import static java.lang.Math.max;",
                        "import java.util.ArrayList;"))));
        check("blanks dropped and duplicates removed",
                "[import java.io.File;, import java.util.List;]",
                String.valueOf(ImportStatementOrganizer.organize(list(
                        "import java.util.List;", "   ", "import java.io.File;",
                        "import java.util.List;", ""))));
        check("two static imports sort among themselves",
                "[import java.util.Set;, import static java.lang.Math.abs;, import static org.junit.Assert.assertEquals;]",
                String.valueOf(ImportStatementOrganizer.organize(list(
                        "import static org.junit.Assert.assertEquals;",
                        "import static java.lang.Math.abs;",
                        "import java.util.Set;"))));
        check("indentation is stripped", "[import java.util.Map;]",
                String.valueOf(ImportStatementOrganizer.organize(list("      import java.util.Map;"))));
        check("empty input", "[]",
                String.valueOf(ImportStatementOrganizer.organize(list())));
        finish();
    }
}

