public class ImportStatementOrganizer {

    public static String importedName(String line) {
        String text = line.trim();
        if (text.startsWith("import ")) {
            text = text.substring("import ".length()).trim();
        }
        if (text.startsWith("static ")) {
            text = text.substring("static ".length()).trim();
        }
        if (text.endsWith(";")) {
            text = text.substring(0, text.length() - 1);
        }
        return text.trim();
    }

    public static boolean isStatic(String line) {
        return line.trim().startsWith("import static ");
    }

    public static java.util.List<String> organize(java.util.List<String> lines) {
        java.util.List<String> cleaned = new java.util.ArrayList<>();
        for (String line : lines) {
            String text = line.trim();
            if (!text.isEmpty() && !cleaned.contains(text)) {
                cleaned.add(text);
            }
        }
        cleaned.sort(java.util.Comparator
                .comparing(ImportStatementOrganizer::isStatic)
                .thenComparing(ImportStatementOrganizer::importedName));
        return cleaned;
    }
}
